});
if (ref.object.sha !== expectedMain) {
  core.setFailed(`Current ${repository.default_branch}=${ref.object.sha} differs from requested ${expectedMain}.`);
  return;
}

const priorComments = await github.paginate(github.rest.issues.listComments, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: priorControlPr,
  per_page: 100,
});
const priorResult = priorComments.find((comment) => {
  const text = String(comment.body || '');
  return text.startsWith(priorResultPrefix) &&
    text.includes(`run-id: ${priorRunId}`) &&
    text.includes('state: EXECUTION_NOT_QUALIFIED_REVIEW_ARTIFACT_BEFORE_ANY_RETRY') &&
    text.includes(`artifact-id: ${priorArtifactId}`) &&
    text.includes(`artifact-digest: ${priorArtifactDigest}`) &&
    text.includes('Automatic replay is forbidden.');
});
if (!priorResult) {
  core.setFailed('Exact failed V1 result receipt is missing from PR128; reconciliation lineage is incomplete.');
  return;
}
const { data: priorArtifact } = await github.rest.actions.getArtifact({
  owner: context.repo.owner,
  repo: context.repo.repo,
  artifact_id: priorArtifactId,
});
const expectedArtifactDigest = `sha256:${priorArtifactDigest}`;
if (
  priorArtifact.expired ||
  priorArtifact.name !== priorArtifactName ||
  priorArtifact.digest !== expectedArtifactDigest ||
  String(priorArtifact.workflow_run?.id || '') !== priorRunId
) {
  core.setFailed('Exact preserved V1 evidence artifact is unavailable or has changed identity.');
  return;
}

const comments = await github.paginate(github.rest.issues.listComments, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: controlPr,
  per_page: 100,
});
const priorMarker = comments.find(
  (comment) => String(comment.body || '').startsWith(markerPrefix)
);
if (priorMarker) {
  core.setFailed(
    `A prior V2 execution-attempt marker already exists at comment ${priorMarker.id}; ` +
    'automatic replay remains forbidden and requires a new reviewed reconciliation boundary.'
  );
  return;
}

const marker = await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: controlPr,
  body: [
    markerPrefix,
    'ATHENA reconciled PR69 primary time-basis evidence campaign V2 attempt started.',
    `run-id: ${context.runId}`,
    `main-sha: ${expectedMain}`,
    `command-comment-id: ${context.payload.comment.id}`,
    `reconciled-from-run-id: ${priorRunId}`,
    `reconciled-artifact-id: ${priorArtifactId}`,
    `reconciled-artifact-digest: ${priorArtifactDigest}`,
    `fix-pr: ${fixPr}`,
    `fix-merge-sha: ${fixMergeSha}`,
    'state: ATTEMPT_STARTED_NO_RESULT_YET',
    'Automatic replay is forbidden if this V2 run does not complete cleanly.',
  ].join('\n'),
});
core.setOutput('main_sha', expectedMain);
core.setOutput('marker_comment_id', String(marker.data.id));

const campaignExit = process.env.CAMPAIGN_EXIT_CODE || '';
const postExit = process.env.POST_STATUS_EXIT_CODE || '';
const packageOutcome = process.env.PACKAGE_OUTCOME || '';
const assessOutcome = process.env.ASSESS_OUTCOME || '';
const assessmentValid = process.env.ASSESSMENT_VALID || '';
const artifactOutcome = process.env.ARTIFACT_UPLOAD_OUTCOME || '';
const artifactId = process.env.ARTIFACT_ID || '';
const artifactDigest = process.env.ARTIFACT_DIGEST || '';
const artifactUrl = process.env.ARTIFACT_URL || '';
const ok = campaignExit === '0' &&
  postExit === '0' &&
  packageOutcome === 'success' &&
  assessOutcome === 'success' &&
  assessmentValid === 'true' &&
  artifactOutcome === 'success' &&
  artifactId.length > 0;
const state = ok
  ? 'PRIMARY_EVIDENCE_CAMPAIGN_V2_EXECUTED_AND_PRESERVED_PENDING_SEMANTIC_QUALIFICATION'
  : 'EXECUTION_V2_NOT_QUALIFIED_REVIEW_ARTIFACT_BEFORE_ANY_FURTHER_RETRY';
const resultPrefix = '<!-- ATHENA_PR69_PRIMARY_TIME_BASIS_EVIDENCE_EXECUTION_RESULT_V2 -->';
await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: 130,
  body: [
    resultPrefix,
    'ATHENA reconciled PR69 primary time-basis evidence campaign V2 result.',
    `run-id: ${context.runId}`,
    `main-sha: ${process.env.AUTHORIZED_MAIN_SHA || ''}`,
    `state: ${state}`,
    `campaign-exit-code: ${campaignExit}`,
    `post-status-exit-code: ${postExit}`,
    `package-outcome: ${packageOutcome}`,
    `assessment-outcome: ${assessOutcome}`,
    `assessment-valid: ${assessmentValid}`,
    `artifact-upload-outcome: ${artifactOutcome}`,
    `artifact-id: ${artifactId}`,
    `artifact-digest: ${artifactDigest}`,
    `artifact-url: ${artifactUrl}`,
    'reconciled-from-run-id: 31953949073',
    'reconciled-artifact-id: 9266604353',
    'fix-pr: 129',
    'fix-merge-sha: 94577458d4b8af59a4e986edb2e4df9c426e21be',
    'semantic-extraction: false',
    'historical-effective-scope-qualification: false',
    'pr69-source-local-time-basis-resolution: false',
    'pr80-constructor-input: false',
    'model/probability/pricing/selection/production/BET authority: false',
    ok
      ? 'No semantic conclusion is authorized by successful acquisition alone.'
      : 'Automatic replay remains forbidden. Review the preserved V2 artifact before any further retry.',
  ].join('\n'),
});
if (!ok) {
  core.setFailed('Reconciled V2 execution did not satisfy the complete preserved-evidence gate.');
}
